import { test } from "node:test";
import assert from "node:assert/strict";
import { createRenderer } from "../web/effect-preview.js";
import { readEffectMetadata } from "../build_effects.mjs";
const metadata = await readEffectMetadata();
const base = { effect: 0, color: "#ff0000", brightness: 100, on: true, speed: 255, intensity: 128 };

// Sample on WLED's 23 ms tick so counter and pixel-boundary assertions refer to actual frames.
function sample(effect, time, params = {}) {
	const renderer = createRenderer(metadata);
	const state = { ...base, effect, ...params };
	renderer.frame(state, 0);
	return renderer.frame(state, time);
}

test("all local effect IDs have a strip frame or an explicit missing-input result", () => {
	assert.equal(Object.keys(metadata).length, 217);
	for (const id of Object.keys(metadata).map(Number)) {
		const renderer = createRenderer(metadata);
		for (const time of [0, 23, 230, 920, 2300]) {
			const pixels = renderer.frame({ ...base, speed: 128, effect: id }, time);
			if ([53, 77].includes(id)) {
				assert.equal(pixels, null);
				assert.match(renderer.description(id), /needs/);
			} else {
				assert.equal(pixels.length, 30, metadata[id].name);
				assert.ok(pixels.every((pixel) => /^[0-9a-f]{6}$/.test(pixel)), metadata[id].name);
			}
		}
	}
});

test("Blink follows FX.cpp::blink duty-cycle timing and uses a black secondary color", () => {
	// sx=0: cycle=5100+46ms, ix=0: onTime=23ms. All LEDs are on/off together.
	assert.ok(sample(1, 23, { speed: 0, intensity: 0 }).every((p) => p === "ff0000"));
	assert.ok(sample(1, 46, { speed: 0, intensity: 0 }).every((p) => p === "000000"));
	assert.ok(sample(1, 5152, { speed: 0, intensity: 0 }).every((p) => p === "ff0000"));
});

test("Wipe clears in the forward direction; Sweep clears in reverse (FX.cpp::color_wipe)", () => {
	// sx=255: 750ms cycle, 552ms lies in the clearing half; the boundary is LED 14.
	const wipe = sample(3, 552), sweep = sample(6, 552);
	assert.ok(wipe.slice(0, 14).every((p) => p === "000000"));
	assert.ok(wipe.slice(15).every((p) => p === "ff0000"));
	assert.deepEqual(sweep, [...wipe].reverse());
});

test("Scan uses the exact block width and position from FX.cpp::scan", () => {
	// size=1+((128*30)>>9)=8, prog=floor(552*65535/750), offset=abs(((prog*44)>>16)-22)=10.
	const scan = sample(10, 552);
	assert.deepEqual(scan.map((p, i) => p === "ff0000" ? i : -1).filter((i) => i >= 0), [10, 11, 12, 13, 14, 15, 16, 17]);
});

test("Colorloop colors the whole strip; Rainbow repeats the color wheel according to intensity", () => {
	assert.equal(new Set(sample(8, 552)).size, 1);
	assert.ok(new Set(sample(9, 552)).size > 20);
	// ix=232: 16<<(232/29)=4096, giving repeated wheel cycles rather than a generic smooth hue field.
	const repeated = sample(9, 552, { intensity: 232 });
	assert.notDeepEqual(repeated, sample(9, 552, { intensity: 29 }));
});

test("matrix-only effects use the firmware's static fallback on a 1D base", () => {
	for (const id of [122, 153, 220]) assert.ok(sample(id, 2300).every((p) => p === "ff0000"));
});

test("effect-specific palette/custom defaults come from this checkout's metadata", () => {
	assert.equal(metadata[219].pal, 2);
	assert.deepEqual(createRenderer(metadata).defaults(219), { speed: 0, intensity: 0 });
	assert.equal(metadata[216].c3, 23);
});

test("Slow Transition holds its current color and blends to a changed target over ten seconds at sx=0", () => {
	const renderer = createRenderer(metadata);
	const state = { ...base, effect: 219, speed: 0 };
	assert.equal(renderer.frame(state, 0)[0], "ff0000");
	assert.equal(renderer.frame(state, 1000)[0], "ff0000");
	const blue = { ...state, color: "#0000ff" };
	assert.equal(renderer.frame(blue, 1000)[0], "ff0000");
	assert.equal(renderer.frame(blue, 11000)[0], "0000ff");
});

test("brightness and power scale output without changing effect phase or sharing state between views", () => {
	const a = createRenderer(metadata), b = createRenderer(metadata);
	const state = { ...base, effect: 42 };
	a.frame(state, 0); b.frame(state, 0);
	const expected = a.frame(state, 2300);
	const dim = b.frame({ ...state, brightness: 50 }, 2300);
	assert.deepEqual(dim, expected.map((p) => p.match(/../g).map((part) => ((parseInt(part, 16) * 129) >> 8).toString(16).padStart(2, "0")).join("")));
	assert.ok(b.frame({ ...state, on: false }, 2323).every((p) => p === "000000"));
	assert.equal(createRenderer(metadata, 7).frame(base, 0).length, 7);
});

test("reduced motion freezes simulation time", () => {
	const renderer = createRenderer(metadata);
	const state = { ...base, effect: 9 };
	assert.deepEqual(renderer.frame(state, 0, true), renderer.frame(state, 5000, true));
});
